<?php $adminTitle='Sayfa Oluşturucu'; $adminActive='pages'; require BASE_PATH.'/resources/views/admin/_header.php'; ?>
<h1>CMS - Sayfalar</h1><p><a href="<?= e(url('/admin')) ?>">Yönetim paneli</a></p><?php if(!empty($_SESSION['success'])): ?><p class="success"><?= e($_SESSION['success']) ?></p><?php unset($_SESSION['success']); endif; ?><?php if(!empty($_SESSION['error'])): ?><p class="alert"><?= e($_SESSION['error']) ?></p><?php unset($_SESSION['error']); endif; ?>
<section class="admin-card homepage-picker"><h2>Ana sayfa seçimi</h2><p>Ana domainin kök adresinde gösterilecek yayınlanmış sayfayı seçin.</p><form method="post" action="<?= e(url('/admin/pages/homepage')) ?>"><?= csrf_field() ?><label>Yayınlanmış sayfa</label><select name="page_id"><option value="0">Varsayılan (home sayfası)</option><?php foreach($pages as $candidate): if($candidate['status']!=='published') continue; ?><option value="<?= (int)$candidate['id'] ?>" <?= $homepageId===(int)$candidate['id']?'selected':'' ?>><?= e($candidate['title']) ?></option><?php endforeach; ?></select><button type="submit">Ana sayfa olarak kaydet</button></form></section><h2>Yeni sayfa</h2><form method="post" action="<?= e(url('/admin/pages/store')) ?>"><?= csrf_field() ?><label>Başlık</label><input name="title" required><label>Slug</label><input name="slug" required><label>İçerik (HTML)</label><textarea name="content" rows="10"></textarea><label>Durum</label><select name="status"><option value="draft">Taslak</option><option value="published">Yayında</option></select><label>Meta başlık</label><input name="meta_title"><label>Meta açıklama</label><textarea name="meta_description"></textarea><button type="submit">Oluştur</button></form>
<h2>Mevcut sayfalar</h2><?php foreach($pages as $page): ?><section class="site-card"><form method="post" action="<?= e(url('/admin/pages/update')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$page['id'] ?>"><label>Başlık</label><input name="title" value="<?= e($page['title']) ?>" required><label>Slug</label><input name="slug" value="<?= e($page['slug']) ?>" required><label>İçerik (HTML)</label><textarea name="content" rows="10"><?= e($page['content']) ?></textarea><label>Durum</label><select name="status"><option value="draft" <?= $page['status']==='draft'?'selected':'' ?>>Taslak</option><option value="published" <?= $page['status']==='published'?'selected':'' ?>>Yayında</option></select><label>Meta başlık</label><input name="meta_title" value="<?= e($page['meta_title']) ?>"><label>Meta açıklama</label><textarea name="meta_description"><?= e($page['meta_description']) ?></textarea><button type="submit">Güncelle</button></form><form method="post" action="<?= e(url('/admin/pages/delete')) ?>" onsubmit="return confirm('Sayfa silinsin mi?');"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$page['id'] ?>"><button type="submit">Sil</button></form><p>Önizleme: /<?= e($page['slug']) ?></p></section><?php endforeach; ?><?php require BASE_PATH.'/resources/views/admin/_footer.php'; ?>
